#!/bin/sh
# Rebuild the single-file demo from its chunks (order matters).
# k0.js is generated: python ../../catalogue/tools/build_app_data.py k0.js
# s0.js is the greenhouse engine (3D sheets, palettes, shadows, necks), l0.js the 2.5D L-system (plants grown with their axes, buds and leaves); s1a..s9a.js the species redone lot by lot
# v0.js is generated: python ../../catalogue/tools/build_vases.py v0.js (vessels measured on the reference photos)
